quests[41945] = { id = 41945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tianji of the Ox", description = "Greetings, Grandmaster. Beside me is the Scouting Map. From it, you can direct our allies to carry out vital assignments across the Broken Isles.\n\nThe first task is critical. Tianji, a renowned trainer in the ox school style of martial combat, was on her way to the Broken Isles when she was attacked.\n\nI suggest we send Chen Stormstout to help her. He will be uniquely suited to this task.", progress = "How is the mission proceeding?", completion = "Most excellent, Grandmaster! The mission was a success. Our new teacher, Recruiter Tianji, is getting situated as we speak.", objectives = "Use the Scouting Map and complete the mission, \"Tianji Needs Help\".", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41946] = { id = 41946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Building Our Troops", description = "Our champions acquired the talents of Recruiter Tianji, a famed monk skilled in the school of the ox.\n\nShe is known for her brewmaster techniques, and is a valuable addition to the temple. She is already beginning to train a new batch of pupils.\n\nSpeak to her now and train an initiate of the ox.", progress = "How did the training go?", completion = "Excellent. These troops will be invaluable in our defense of the Broken Isles. Deploy them on missions, just as you would with our champions.", objectives = "Speak to Recruiter Tianji and train an Ox Initiate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
