quests[41949] = { id = 41949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Drekirjar Return" }
quests[41950] = { id = 41950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cry More Thunder!", description = "You have proven yourself an ally of the Thorignir and we will lend you our strength. I would ask one last favor of our new champion, though. \n\nThe dragon who guided you to me awaits his vengeance against the vrykul. Together I wish for you to show these Drekirjar what it means to cross the Thorignir. Their toll must be paid in blood.\n\nSpeak to Vethir when you are ready.", objectives = "Fly with Vethir and kill 150 of the God-King's allies in Hrydshal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
