quests[41957] = { id = 41957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Vindicator's Plea", description = "I've obtained a request from Vindicator Boros in Dalaran asking for our help.\n\nHe has recovered a soldier who escaped from the Legion! He was injured and his wounds are resisting every healing treatment available to them. Normally this would fall to an acolyte to handle, but the soldier mentioned T'uure in his delirium! I thought the holy gem was lost!\n\nYou are strong with the Light, perhaps you can succeed where they can't?\n\nIf you need it, Brother Larry can provide you with a flight to Dalaran.", completion = "Thank you for arriving in such haste, Brother.", objectives = "Meet with Vindicator Boros in front of First to Your Aid in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41958] = { id = 41958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh, Ominitron" }
