quests[41961] = { id = 41961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Black Rook Holdings", description = "Inside the chest, hidden amongst various knickknacks, is a signet engraved with a unique crest.\n\nThe band, made from a silvery, unbreakable metal, has been worn down by time, as if absently twisted and rubbed against its owner's finger.", objectives = "Take the Warden's Signet to Jarod Shadowsong.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
