quests[41965] = { id = 41965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lunarwing Liberation" }
quests[41966] = { id = 41966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "House Call", description = "I thought Barrem was lost to us after the tragedy at Broken Shore, Light knows we lost far too many good soldiers just like him there.\n\nI was shocked to see he was still alive when one of our patrols arrived carrying him. They found him floating in the sea with wounds that would kill any lesser draenei.\n\nThere is something about those wounds that resists everything we've done to treat them. Please, {class}, as a brother in the Light I ask you to do all that you can to help him to recover.", completion = "I... I owe you my life, brother, but that look on your face tells me you're here for something else.\n\n<You tell Barrem about his mentioning of T'uure in his sleep.>\n\nI must have been dreaming of Alora, she was my cell mate in that accursed world the demons took me to. She told me she saw the crystal but never said much else.\n\nI just hope she is still alive.", objectives = "Treat the wounds of Defender Barrem.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41967] = { id = 41967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out of the Darkness", description = "Alora and I were were able to escape through one of the Legion's portals back to Azeroth but that's about as far as our luck got us.\n\nThe portal put us on a small isle somewhere to the west of the Broken Shore. They saw us quickly and we made a run for the protection of the water. As I attempted to leap to safety, I was wounded. But Alora... she tripped and I watched them drag her back.\n\nRescue her, please! I'll mark where the camp is on your map, just don't let her go through that ordeal again.", completion = "I felt my soul being ripped from my body. If you hadn't come when you did... I don't even want to think about it!\n\nIs there anything I can do to repay you? I owe you my life after all.\n\n<You mention to her Barrem's story.>\n\nBarrem still lives too? Oh thank the light! Yes, I'll gladly tell you everything I know.", objectives = "Travel to Darkstone Isle near the Broken Shore and search for Alora.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
