quests[41980] = { id = 41980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Temple Defense" }
quests[41981] = { id = 41981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Traversing the Heavens", description = "If you are not opposed, {name}, I would accompany you on your journey through Skywall.\n\nThere are wonders here that my eyes have never before beheld, and it would be my great honor to join you.\n\nOur quest to resurrect the mighty Thunderaan and unite the four great elemental lords will be no easy task.\n\nLead the way, Farseer, and I shall follow.", objectives = "Escort Farseer Nobundo through the Vortex Pinnacle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41982] = { id = 41982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Book Read Tracking Quest" }
