quests[41988] = { id = 41988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Strong Defense" }
quests[41989] = { id = 41989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood of My Blood", description = "As my darling <brother/sister> has demonstrated, Elisande's decision to bring down the shield has sown unrest among the nightborne.\n\nLoyalists and demons march together in the streets. Fear and distrust grip our hearts. Family turns against family.\n\nI will help Thalyssra stir a new rebellion, but first we must deal with Anarys.\n\nI do not wish to spill the blood of my blood - only to help <him/her> see reason.\n\nAnarys is likely brooding over our father's memorial. Bring <him/her> to me alive.", progress = "Anarys could halt our efforts before they begin.", completion = "Thank you. Now our work can begin.", objectives = "Defeat Anarys Lunastre and deliver <him/her> to Ly'leth Lunastre.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[41990] = { id = 41990, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chopped" }
