quests[41992] = { id = 41992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twisted Ash" }
quests[41993] = { id = 41993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salvation From On High", description = "I was serving aboard the airship that crashed on the way to the Broken Shore. I must have blacked out as the next thing I remember was being jolted awake. I was on a broken land and above me stood a man'ari carrying a staff of darkened crystal. There is no mistaking it, that staff was T'uure!\n\nAll my life I've heard stories about how T'uure flowed with the healing power of the light. Somehow the crystal has been darkened by Man'ari. We must get it back and restore it to its pure form!", completion = "You seek a demon with a staff of crystal? The Eredar that calls itself Lady Calindris has one that matches your description perfectly.\n\nShe's MY prey though! I've been chasing her minion all over the isles and I'm not about to let this opportunity pass.\n\nI could use someone to watch my back though. If you help me out I'd be willing to let you take this staff you seek. I don't care about her equipment, it's her soul that I'm after.\n\nWell, what do you say?", objectives = "Something unexpected has interrupted your discussion, deal with it!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
