quests[42000] = { id = 42000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeker of Truth", description = "You may be familiar with Orik Trueheart. He has devoted his time after the Northrend campaign to learning more about Tyr. \n\nOrik has evidence of a powerful shield crafted by Tyr long ago. With the help of the Sunwalkers, we may finally be able to seek it out.\n\nPlease speak to him immediately.", progress = "I'm glad yer in. We've quite the journey ahead.", completion = "I'm glad yer coming. I've been wanting to pursue this for some time now. With help from the Seers, I think it can be done!", objectives = "Speak with Orik Trueheart in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42001] = { id = 42001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aluneth, Greatstaff of the Magna", description = "Aluneth... a powerful and dangerous weapon. If tales are to be believed, Aluneth is actually the name of a very old and very powerful arcane entity, somehow bound to a staff through ancient magic.\n\nWhen Aegwynn relinquished Aluneth many years ago, it was entrusted to Kirin Tor, who, fearing its unbridled power, handed it to the blue dragonflight to secure away in secret. Only they would know exactly where it was taken.\n\nThe dragon Kalec may be our best chance. He now resides on the Council of Six.", completion = "So you seek Aluneth? A dangerous weapon, to be sure.\n\nLong ago the Kirin Tor entrusted the blue dragonflight with its safekeeping. It was locked away in the only place that could contain its rampant power  - the Nexus Vault.\n\nI have not been there in some time, however. After the blue dragonflight was dissolved, the Nexus was all but abandoned. There is no knowing whether the Nexus Vault is still intact - or what may be waiting in the Nexus itself.", objectives = "Meet Kalec at the Violet Citadel in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42002] = { id = 42002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Northrend", description = "Naturally I've done some legwork already. I believe this Gorvold is buried at Shield Hill in the Howling Fjord.\n\nTahu can help locate the grave, and with a short ritual we should have our answers!\n\nMeet us at Shield Hill in the Howling Fjord and we'll move on to the next step.", completion = "I trust the journey wasn't too long or hard.\n\nLet's go find our dead adventurer, eh?", objectives = "Meet Orik Trueheart on Shield Hill in Howling Fjord.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42003] = { id = 42003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kept Secret, Kept Safe", description = "With the scrolls in hand, now you must set to the task of finding the staff.\n\nWhen Aegwynn relinquished it many years ago, it was entrusted to Kirin Tor, who, fearing its unbridled power, handed it to the blue dragonflight to secure away from the hands of men. Only they would know exactly where it was taken, or how to retrieve it.\n\nThe dragon Kalec may be our best chance. He now resides upon the Council of Six in Dalaran. Seek him, and your answers, there.", sourceObjective = "Meet Kalec at the Violet Citadel in Dalaran.", sourceObjectiveStatus = "unverified-source-field" }
quests[42004] = { id = 42004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ghostship" }
quests[42005] = { id = 42005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The End of the Saga", description = "Ye should read the saga yerself, it's right here.\n\nWe're here to speak to the spirit of that vrykul I spoke of. Tahu Sagewind is a powerful Seer and he should be able to bring his spirit back. It will be up to us to convince him to speak.\n\nYou should speak with Tahu so we can get started.", completion = "I think I already have a lead on that island. Word around the tavern was a great warrior had broken into a vrykul king's tomb on an island in Stormheim.\n\nThat's got to be the one we're looking for!", objectives = "Get the end of the story from the spirit of the saga hero.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42006] = { id = 42006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Threat", description = "If you seek the Nexus, be wary. There are strange happenings in Coldarra, and it would be best to understand them before proceeding.\n\nDuring my last visit to Dragonblight, I sensed unusual energies from the Azure Dragonshrine. Since this place was integral to Malygos' plans during the Nexus War, whatever is there may explain the current state of the Nexus.\n\nHere, take this image crystal. I must remain in Dalaran on Kirin Tor business, so we will speak through it. Good luck.", progress = "The communication device is inactive.", completion = "This appears to be a communication device commonly utilized by the ethereals.\n\nPerhaps it could be the key to finding out who is behind the happenings at the Dragonshrine.", objectives = "Search the Azure Dragonshrine for clues regarding the current state of the Nexus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42007] = { id = 42007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Forgotten Enemy", description = "The device still hums with power. It must have been abandoned not long ago.\n\nThe nearby switch appears to activate it.", objectives = "Activate the Ethereal Communication Device at the Azure Dragonshrine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42008] = { id = 42008, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eyes of the Dragon", description = "You should travel at once to Coldarra in Borean Tundra, {name}. There, I would recommend you scout out a few key locations and report back to me. \n\nI know the area well, and should be able to tell you how to proceed.\n\nMake haste!", objectives = "Scout out the key locations in Coldarra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42009] = { id = 42009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harnessing the Arcane", description = "The energy from Aluneth lashes out from within the weakened Nexus Vault.  We may be able to use this raw, chaotic energy to our advantage.\n\nIf we can harness this energy and feed it into the Surge Needles, it should cause a rather... destructive reaction.", objectives = "Empower yourself with Unstable Arcane Energy by defeating Arcane Aberrants or siphoning from Breaches of Arcane Energy around the foundation of the Nexus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42010] = { id = 42010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arcane Unleashed", description = "You have the power you need to destroy the Surge Needles. \n\nAt the location of the breaches where the Surge Needles pierce the ground, there will be a large concentration of void energy. Focus the power of Aluneth into these points. The reaction should cause an overload, destroying the Surge Needle above.\n\nYou must act quickly. The Ethereum won't sit idly by as you lay waste to their machinations.", objectives = "Use your built up Unstable Arcane Energy to destroy the Surge Needles in Coldarra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42011] = { id = 42011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nexus Vault", description = "If the Ethereum managed to capture Azuregos, then they are more powerful than I imagined. \n\nWe have not always seen eye to eye, Azuregos and I, but he is still my kin. Since you seek to put an end to the ethereals and claim Aluneth, I ask that you also free my brother from their grip.\n\nWith the Surge Needles destroyed, the shield has dissipated. The Nexus awaits, {name}.", completion = "You have my gratitude for saving Azuregos, {name}. I can rest easy knowing that the Nexus is under his care.\n\nAs for you, I can see you're full of surprises. Never in my time have I seen a {class} who can control the chaotic energies of Aluneth. \n\nThank you for what you have done for me and my kind today. You are truly the hero we need to face the Legion.", objectives = "Defeat Nexus-Prince Bilaal and claim Aluneth, Greatstaff of the Magna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42012] = { id = 42012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift of Time", description = "You have done a great thing for the blue dragons today, {name}, as well as for my own peace of mind.\n\nNow, armed with Aluneth, I only ask that you fulfill your original goal, and take the fight to the Legion.\n\nI believe your comrades await your back in the Hall of the Guardian. Safe travels, friend.", objectives = "Meet Meryl Felstorm in the Hall of the Guardian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42013] = { id = 42013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Helmouth" }
