quests[42027] = { id = 42027, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Faronaar in Chaos" }
quests[42028] = { id = 42028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Nightmare" }
quests[42031] = { id = 42031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dire Growth", description = "Naralex asks for you to join him. He is ready to analyze the sample that he brought back from Shaladrassil.", progress = "I have never seen anything like this...", completion = "You were just with Naralex? What were the results of the sampling?", objectives = "Meet with Naralex, plant the Lasher Seed, and analyze its effects.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42032] = { id = 42032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sampling the Nightmare", description = "There is still so much that we don't know about the Nightmare.\n\nBefore we can fight it, we must understand how it spreads.\n\nLet us send our champions to the roots of Shaladrassil in Val'sharah, and ask them to bring back samples to study.", completion = "Our champions returned from Shaladrassil just moments ago, Archdruid. The journey was a great success!", objectives = "Complete the mission, \"Sampling the Nightmare.\"", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42033] = { id = 42033, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malorne's Refuge", description = "I see... it is as we have always feared. The Emerald Nightmare has found our world.\n\nWe must call upon the ancient god, Malorne.\n\nTravel southeast to the shrine at Malorne's Refuge. There, we druids have kept a sacred relic for thousands of years, a gift from the white stag himself.\n\nI already sent Broll Bearmantle ahead to give word of your arrival.", completion = "I'm glad you are here, {name}, but if only we had arrived earlier! This place was in chaos when I arrived.\n\nThe survivors claim they were attacked by satyr, but how can this be? No satyrs have roamed these woods since ancient times.", objectives = "Speak to Broll Bearmantle at Malorne's Refuge in Val'sharah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42034] = { id = 42034, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grip of Nightmare", description = "Most of the druids were able to escape, but the shrine is still swarming with enemies.\n\nThe shrine's leader, Sylendra  Gladesong, stayed behind to recover Malorne's Idol. We must go back and help her.", completion = "The satyr have never been this bold, or powerful. They took us completely by surprise, and our magic could not withstand their attacks. Without you, I would not have survived.\n\nI have only one purpose now - to recover that idol.", objectives = "Kill 5 Darkfiend Raiders, rescue Sylendra Gladesong, and examine the Altar of Malorne.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42035] = { id = 42035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking the Enemy", description = "The Idol may be stolen, but there is still hope.\n\nWhile I was trapped at the shrine, I saw the satyr raiders make off with the relic. Their tracks will still be fresh.\n\nWith our heightened senses, we may still be able to pick up their trail.\n\nWe must follow their signs through the forest and recover the Idol!", completion = "Look what we dragged in.", objectives = "Use your Cat Form to follow the satyr's tracks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42036] = { id = 42036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Idol of the Wilds", description = "We were able to wrest a confession out of this one. We know that their leader took the idol into Moonclaw Vale, but he could be hiding anywhere.\n\nSurely one of these satyrs will know where it was taken.\n\nGet the information out of these satyrs, even if it's the last thing they do.", progress = "Did you recover the Idol of the Wilds?", completion = "The Idol... so relieved am I to see it in your hands, {name}.\n\nWe will keep it here at the Dreamgrove for safekeeping.", objectives = "Attack 6 Darkfiend Satyr and extract information about the Idol of the Wilds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42037] = { id = 42037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gathering the Dreamweavers", description = "Now that you've recovered the Idol of the Wilds, it's time to put it to use to commune with Malorne. However, the ritual will need the combined power of many druids.\n\nSend your champions to gather the druids of our order, and tell them to meet us in Nordrassil. We will need to do this together.", completion = "Good, the druids have gathered. Even now, they should be flocking to Nordrassil to prepare for the ritual.", objectives = "Retrieve druids by completing \"Gathering the Dreamweavers\" missions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42038] = { id = 42038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Broll Bearmantle", objectives = "I have seen enough of the Nightmare to know that it is not an idle threat. Within its grasp, even the strongest become their own worst enemies.\n\nYou, however, have displayed courage and fortitude even in the face of this great danger. I feel faith that you will lead us to victory against our enemy.\n\n{name}, I wish to pledge my loyalty in service of you and the druidic order", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42039] = { id = 42039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Sylendra Gladesong", objectives = "{name}, I owe you my life. Your actions gave me a second chance, and it is a chance I have no intention of squandering.\n\nWith your help, we were able to recover the Idol of the Wild. Such a sacred relic would have been a devastating loss had it fallen into the wrong hands.\n\nNow, I will see this journey through to its end.\n\nLet me fight for you. If there is anyone who can defeat the Nightmare, I believe it is you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42040] = { id = 42040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Way to Nordrassil", description = "The time has come for us to use the Idol of the Wilds and commune with Malorne.\n\nThe ritual will require a great deal of power, so we have decided to convene at Nordrassil and draw upon the World Tree's essence.\n\nThere is no time to waste. The fastest path will be through the Emerald Dreamway. Go ahead, and we will follow.", completion = "Something isn't right here, {name}. This isn't the Dream. Could Xavius' creatures have invaded our sanctuary? How did they get past our protective wards?", objectives = "Speak to Archdruid Hamuul Runetotem in the Emerald Dreamway.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42041] = { id = 42041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enduring the Nightmare", description = "We are under attack here, {name}!\n\nCreatures of the Nightmare are spilling into the Dreamway as we speak.\n\nDestroy them. They cannot be allowed to linger, or else the Nightmare will take root here, too!", progress = "Is it done?", completion = "Good, I already feel the Nightmare's power waning.", objectives = "Kill 12 aberrations of Nightmare.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42042] = { id = 42042, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teensy Weensies!", description = "Oh {name}, I'm so very very happy to see you!\n\nThe woodland critters whispered there was trouble in the Dreamway so I came immediately!\n\nThere are so very many teensy weensy little creatures that live here in the Emerald Dream, and they're out there, all lost and alone!\n\nWould you go out there and gather them up? You can use my flute to call them to you.\n\nThank you, brave druid!", progress = "Ohhh, the teensy weensy fae dragons are so cute! Are they all right?", completion = "Yay, they're saved! Thank you!", objectives = "Use Mylune's Flute to gather 15 Teensy Weensy Fae Dragons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42043] = { id = 42043, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleaning Up", description = "When the Nightmare spreads, it consumes the life force of all that it touches.\n\nThe more it spreads, the weaker our magic becomes.\n\nIn its early stages, before the taint has taken hold, we can still cleanse the affected areas.\n\nI will bless you with Elune's grace. By channeling her power, you can reverse the Nightmare's spread.", progress = "Did you restore the Dream?", completion = "Excellent work, {name}. I knew that Elune's power could purify the nightmare's taint. Her blessing is strong here.", objectives = "Cleanse 100 Nightmare Creep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42044] = { id = 42044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dying Dream", description = "Deep in the heart of the swamp lies an ancient protector of the Dreamway, Witherheart.\n\nHe was among the first defenders to battle against the Nightmare, but he has fallen to total corruption.\n\nIt pains me to say it, but we must destroy him.", progress = "No one is safe from the Nightmare.", completion = "Today I grieve for a fallen ally, one who has wandered these forests for eons.\n\nHe can now be at peace, knowing he gave his life to protect this sacred place.", objectives = "Kill Witherheart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42045] = { id = 42045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Communing With Malorne", description = "Our work here is done, {name}. We have successfully defended the Dreamway. It will be only a matter of time before it is restored to its former state.\n\nBut we have more important matters at hand.\n\nTake the Idol of the Wilds and go onward to Nordrassil. With any luck, they have already gathered. We will meet you there.", progress = "I am glad to see you, {name}.", completion = "My grandfather, Malorne, the ancient god of the wilds himself... long have I wished for this day, only to find that he is in great peril.\n\nIf he is trapped in the Nightmare, then what hope remains for the rest of us?", objectives = "Speak to Remulos at Nordrassil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42046] = { id = 42046, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Beginning", description = "If Malorne is in danger, then things are even worse than I feared. It truly is up to us now.\n\nWe have very little time left. Let us reconvene in the Dreamgrove at once.", completion = "Thank you for all of your heroic efforts, great {class}. Without your help, we could not have recovered the Idol and spoken to Malorne himself.\n\nNow that we know he is trapped in the Nightmare, we can devise a plan.", objectives = "Meet Archdruid Rensar Greathoof at the Dreamgrove in Val'sharah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42047] = { id = 42047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Hamuul Runetotem", objectives = "I have served the wilds for as long as I can remember, mentoring young druids and watching them grow in knowledge and experience.\n\nThere are few who have ascended to the rank of archdruid, but I believe you can become one of our best.\n\nI would be honored to follow your leadership of the grove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42048] = { id = 42048, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Mylune", objectives = "Oh, hi {name}! My woodland friends just couldn't stop talking about you after you left, and it was they who convinced me to come find you here!\n\nA noble {class} with your courage and kindness just doesn't come along every day.\n\nThis is going to be SO much fun, don't you think?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42049] = { id = 42049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Powering the Portal", description = "If Malorne is trapped in the Nightmare, we must try to save him. It may sound like a fool's errand, but we cannot sit by idly.\n\nThere is an abandoned portal within the Emerald Dreamway, one that we druids closed long ago because it leads to the Rift of Aln.\n\nTo infuse it with energy once again, we will need shards of Nightmare which can be found on satyr lieutenants.\n\nSend our champions to hunt and kill these enemies.", progress = "How many shards have we collected?", completion = "Excellent. These shards are positively surging with negative energy. Be careful when touching them, {name}.", objectives = "Collect 10 Shards of Nightmare from \"Powering the Portal\" missions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42050] = { id = 42050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defenders of the Dream", description = "Never has our order faced such a difficult challenge. To succeed, we must rely on each other's strengths.\n\nHowever, we only have a few defenders to spare for the battle ahead.\n\nBroll, Sylendra, Zen'tabra, and Mylune have all volunteered to accompany you into the valley below, but I can only spare one.\n\nWhich one will you choose to aid you in battle?", progress = "Have you chosen?", completion = "Well chosen. The others will aid me in defending here. We must hurry.", objectives = "Choose an ally.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42051] = { id = 42051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enter Nightmare", description = "The portal to the nightmare is ready, {name}. Remulos and the others have already gone ahead.\n\nThere is no telling what horrors await on the other side, {name}. Good luck.", completion = "Do not be deceived, {name}. What appears to be the mountains of Hyjal, is in fact an illusion created by our enemy.\n\nThis is a re-creation of the darkest nightmare in Malorne's mind. This is the War of the Ancients, a battle that occurred thousands of years ago.\n\nIt was during this war that Azeroth was first threatened by the Burning Legion, and the War in which Malorne and the Wild Gods fell.", objectives = "Go through the Nightmare Portal in the Emerald Dreamway.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42052] = { id = 42052, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shade of Xavius", description = "Brightwing loves nice things - rainbows, unicorns, and flowers! But enemies, Brightwing does not forget. Brightwing remembers for a long, long time those that hurt the grove.\n\nNow, we must destroy our enemies... so that the grove can be nice and happy forever!\n\nFriend, go to Darkheart Thicket beneath the roots of Shaladrassil.\n\nThere, find the one named Xavius... the one who started it all. Kill him, and bring me his head.", objectives = "Retrieve the Fragment of Xavius from the Shade of Xavius in Darkheart Thicket.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42053] = { id = 42053, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The War of the Ancients", description = "To free Malorne, we must win the War of the Ancients. A millennia ago, this battle took the combined efforts of the greatest defenders of our world. To win now, we must do the same.\n\nGo upon the battlefield and defeat Legion foes, rescue and revive our allies, and free the innocent who have been caught in the battle. Every enemy defeated and every ally saved will help turn the tide in our favor!", completion = "You lead us to triumph today, {name}.", objectives = "Win the War of the Ancients.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42054] = { id = 42054, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archimonde, The Defiler", description = "We have turned the battle, {name}! The Burning Legion is greatly weakened.\n\nOnly one task remains. Malorne is locked in battle with Archimonde, the demon that slew him ten thousand years ago.\n\nRemember, {name}, we are trapped in Malorne's nightmare. There is no telling what will manifest here, but we MUST do something.\n\nMay Elune guide us, {name}.", completion = "<Malorne gazes directly at you. Radiant, soothing energy exudes outward from his body. Suddenly, you feel a serene sense of peace and gratitude envelop your entire being.>", objectives = "Defeat Archimonde.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42055] = { id = 42055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Demi-God's Return", description = "<Malorne's voice echoes in your mind.>\n\nMortal you may be, but your valor is worthy of the ancient gods.\n\nNature's spirit lives in you - vibrant, wild, and ferocious. I witness in you the essence of nature's spark - the WILL to survive.\n\nOur triumph here will be spoken of for ages to come, {name}.\n\nReturn to the waking world through this portal. We will speak again when we return to the Dreamgrove.", progress = "Nature's cycle is beautiful, but it can be frail. We must preserve its balance.", completion = "{name}, we elders of the Dreamgrove have spoken and all agree. We would like to see you take leadership of the Dreamgrove.\n\nToday, we grant you the title of Arch {class} of the Dreamgrove, a nomination of the highest honor in our order.\n\nWith it, you now carry the responsibility of our order: to protect the wilds! Lead well, {name}.", objectives = "Receive Malorne's blessing.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42056] = { id = 42056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Remulos", objectives = "We have come a long way together, {name}. At every step, your choices have led the Dreamgrove to victory.\n\nI would give my life to defend Azeroth, and I know you would do the same.\n\nGreat danger still faces us. {name}, take my pledge. We must serve and protect the wilds!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42061] = { id = 42061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Charge Trigger Hit" }
quests[42062] = { id = 42062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fight Night: Stitches Jr. Jr." }
quests[42063] = { id = 42063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Size Doesn't Matter" }
quests[42064] = { id = 42064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Illid... Wait." }
quests[42065] = { id = 42065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Twilight Master", description = "There is only one more thing that remains, Farseer {name}. We must confront the leader of the Twilight's Hammer and put an end to their sinister plot once and for all.\n\nWithout their so-called master, the remaining cultists will be forced to retreat from Deepholm.\n\nOnly when The Twilight's Hammer has been crushed and Deepholm has been saved, will we have the support of Therazane against the demons of the Burning Legion.", completion = "So, the Mistress of Twilight was actually a dragon... I thought the brood of Sintharia had all been defeated.\n\nI wonder if Zeryxia was not the last of her kind...", objectives = "Defeat the Mistress of Twilight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42067] = { id = 42067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Howl, No Bite" }
quests[42068] = { id = 42068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Return of Twilight", description = "The Twilight's Hammer has reemerged and they are building an army to overthrow my kingdom. A ludicrous fantasy on their part, but one that I cannot take lightly.\n\nI cannot offer the mortal races my aid until the threat to Deepholm has been dealt with. If you truly wish to unite the Elemental Lords to your cause, I would see you prove it.\n\nGo. Uncover the plot that the Twilight's Hammer is hatching and put an end to their scheme!", completion = "It is good that you have arrived, Farseer {name}. The Twilight's Hammer has built a formidable stronghold here in Deepholm.", objectives = "Speak with Muln Earthfury in Deepholm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42069] = { id = 42069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felbats" }
quests[42070] = { id = 42070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warden Tower Assault: Starstalker's Point" }
quests[42071] = { id = 42071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honoring the Past" }
quests[42072] = { id = 42072, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boros Tracker" }
quests[42073] = { id = 42073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boros Tracker Two" }
quests[42074] = { id = 42074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return of the Light", description = "Excellent!\n\nThere is a gateway further down this pathway and like most Legion constructs it is powered by souls.\n\nI think the death of that Inquisitor should be just enough to activate it and open the way back to where it came from.\n\nLet's go see where the path takes us, shall we?", completion = "It is T'uure! I had thought it was lost to us forever!\n\nWhen I last saw this staff we were escaping from a small world called Niskara. The Legion came upon us unawares, we were only able to escape thanks to a few brave Vindicators who remained behind with T'uure to stall their attack.\n\nI did not think it could be done, but you were able to recover T'uure. You truly walk in the light, {name}. You have my respect, and my thanks.", objectives = "Accompany Jace Darkweaver through the portal and obtain T'uure, Beacon of the Naaru.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42075] = { id = 42075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Botanical Backlash" }
