quests[42077] = { id = 42077, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waking Nightmares" }
quests[42078] = { id = 42078, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ysondre's Seal" }
quests[42079] = { id = 42079, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Masquerade", description = "Our family commands great respect in this city, thanks to my father. Through my network of contacts, we can organize the citizens to prepare Suramar for Thalyssra's return.\n\nYou must walk among the nightborne. You must earn the trust of our friends and foes alike.\n\nYou must become someone else.\n\n<Ly'leth hands you a shimmering party mask.>\n\nPut this on Anarys.", progress = "Not to worry, it will not hurt him.", completion = "My little brother is about to turn over a new leaf, whether he likes it or not.", objectives = "Use the Mask of Mirror Image on Anarys Lunastre.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42080] = { id = 42080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bastion of Bradensbrook" }
quests[42081] = { id = 42081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In With the New", description = "Well, here's your new conduit. Try not to break this one, I really don't feel like making another.\n\nOh, and tell your boss, Deucus, that he owes me big time for this.", completion = "You're finished? Let's see it!\n\n<Deucus takes the conduit from you and places it against the wall.>\n\nNow that is a good looking decoction conduit. I'm glad I upgraded its strength from that old hunk of junk I had before.\n\nYou might even say Svena did me a favor by destroying that old one.", objectives = "Bring the newly forged High-Capacity Decoction Conduit to Deucus in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42082] = { id = 42082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shattered Locus" }
