quests[42087] = { id = 42087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Green Horror" }
quests[42088] = { id = 42088, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evacuate Snowmane", description = "They just keep coming!\n\nAnd now my scouts report some of the drogbar have managed to sneak around our flank and are attacking Snowmane Village.\n\nGo, help the evacuation. We will hold the line here and try to buy you some time.", progress = "I knew we should have secured this town better.", completion = "And not a moment too soon. Our scouts report the Underking himself has come.", objectives = "Evacuate Red Skymane, Tarvim Daywalker, and Old Nefu.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42089] = { id = 42089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fallen Ones" }
quests[42090] = { id = 42090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skittering Subjects" }
