quests[42095] = { id = 42095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nightmare Dragon" }
quests[42096] = { id = 42096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Naralex", objectives = "I've watched you rise up the ranks for a long time, {name}. With you leading our order, I know we are in good hands.\n\nCount me as one of your champions, Archdruid.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42097] = { id = 42097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Searching the Archives", description = "The Black Harvest archives contain an immeasurable amount of magical knowledge that has been collected from various sources over time. \n\nIt's reasonable to think that somewhere among the countless scrolls that we'll find something to aid us in our mission to rescue the remaining council members. \n\nThe search may be exhausting, but it is necessary if we plan to rebuild and face the Burning Legion.", progress = "Have the archives been searched yet?", completion = "Our search of the archives recovered a tome that details the process of creating a demonic gateway. It has the power to access any demon world, assuming we know where to direct it.\n\nWe could use such a gateway to locate and retrieve the remaining council members.", objectives = "Interact with the Dreadscar Battle Plans and complete the mission \"Searching the Archives\".", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42098] = { id = 42098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Black Rook Hold: An Unclaimed Soul", description = "In order to create the anchor, we'll need to link something of Shinfel's to an unclaimed soul.\n\nThe soul will act like a beacon, guiding Shinfel through the Twisting Nether, and back to Dreadscar Rift.\n\nShinfel's staff should provide us with the link we need, but the soul will be a bit harder to find. \n\nDwelling within Black Rook hold is an amalgam of souls, some lost and forgotten. Killing this monstrosity should provide us with the soul we need.", progress = "Have you recovered the soul yet?", completion = "You never disappoint, {name}.\n\nThis otherwise forgotten soul will now serve a greater purpose.", objectives = "Collect an Unclaimed Soul from The Amalgam of Souls in the Black Rook Hold dungeon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42100] = { id = 42100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Empowering the Soul", description = "Creating the anchor will require more power than our soul shards will be able to provide.\n\nDreadscar's troops are capable of amassing a large amount of soul shards when they defeat enemies while on missions. Once we have enough, I can harvest the supply and use them to craft the anchor.", progress = "With enough soul shards, we should have the power to create the anchor.", completion = "Your troops have done well. Our soul shard supply is sufficient enough to create the anchor.", objectives = "Collect Empowered Soul Shards by completing class hall missions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42101] = { id = 42101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Language of the Lost" }
quests[42102] = { id = 42102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Who's Worthy", description = "If we wish to successfully summon the sisters, we'll need the help of a warlock who is skilled in summoning greater demons.\n\nWe cannot afford to lose another council member due to inexperience. \n\nThe Broken Isles are swarming with new blood, all hoping to make a name for themselves in this time of chaos. \n\nHopefully among them we can find one worthy of this council.", completion = "Our scouting efforts have hopefully paid off. I have a lead on a {class} who might possess the skills we need to perform the summoning ritual.\n\nWe should follow up as soon as possible.", objectives = "Interact with the Scouting Map and complete the missions, \"One Who's Worthy\".", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42103] = { id = 42103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let it Feed", description = "We can use the Bloodstone to control the sisters once they are in a weakened state, but first, we'll need to feed it.\n\nThe stone grows in power when consuming the blood of demons. Luckily for us, there's no shortage of demons to kill.", progress = "We will need to feed the Bloodstone before it will be strong enough to control the eredar sisters.", completion = "This should be more than enough blood to satiate the Bloodstone.", objectives = "Kill demons throughout the Broken Isles and collect their blood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42104] = { id = 42104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Underking Comes", description = "Here, I'm too slow to get these laggards to safety. Take my horn and sound the evacuation.\n\nWe need to get the people out of here before the drogbar arrive. The warbraves can take it from there.\n\nFor now just send them over to Spiritwalker Ebonhorn. That fool can watch over them until it is safe.", progress = "Well, this is an unexpected pleasure.", completion = "The Underking is coming. Best keep that weapon of yours handy in case this does not go well.", objectives = "Evacuate Riverbend.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42105] = { id = 42105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mixology Mix-up" }
quests[42106] = { id = 42106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Party Crasher" }
quests[42107] = { id = 42107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On the Trail of the Great Worm", description = "We need the Gjallarhorn to compel the armies of Odyn's children to join our cause. If the great worm swallowed it, we shall dig through the very earth until we find it in its entrails!", completion = "Glory is ours, indeed! The great worm cannot hide from us!", objectives = "Complete the mission \"On the Trail of the Great Worm.\"", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42108] = { id = 42108, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rally the Nightwatchers" }
quests[42110] = { id = 42110, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Summit!", description = "Your armies have tracked the beast to the highest peak in Highmountain.\n\nIt has nowhere left to run, but it is protected by foul drogbar. You must go there yourself and slay Jorhuttam!", completion = "You're after the great worm? You must be very foolish or very brave\n\nI know these mountains inside and out. Help me avenge my village and I will help you find the foul beast.", objectives = "Go to Highmountain Summit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42111] = { id = 42111, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aggressive Reconnaisance" }
quests[42112] = { id = 42112, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Withered Return" }
quests[42113] = { id = 42113, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[42114] = { id = 42114, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ritual of Tides", description = "Long ago, the first Farseer of the Earthen Ring was given a vision of the elements.\n\nIn the vision she foresaw the arrival of a new Farseer, one who would lead us through a time of terrible crisis and unite the elements.\n\n{name}, I believe that you are the Farseer of this prophecy, called to lead before you were ever born.\n\nThe time has come to fulfill your destiny!\n\nWhen you are ready, we will perform the Ritual of Tides and call upon Neptulon, the first of the four great Elemental Lords.", progress = "The time has come to fulfill your destiny, Farseer {name}.", completion = "I have seen you before, Farseer.\n\n<Lord Neptulon judges you silently for a moment before continuing.>\n\nI sense the potential for great power within you. We shall see if this prophecy holds true...", objectives = "Perform the Ritual of Tides in the Maelstrom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42115] = { id = 42115, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Chapter 1 Completed" }
