quests[42118] = { id = 42118, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Chapter 4 Completed" }
quests[42119] = { id = 42119, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Cleansing Cocktail" }
quests[42120] = { id = 42120, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Silver Hand", description = "Too many know of its location, the tomb must be closed forever. First, we must reclaim the hammer.\n\nTyrosus has lent us a force to aid in the recovery of the hammer, and some of my order will meet us there as well, but I fear even that may not be enough. I'm glad we'll have you with us.\n\nTake the portal to Dalaran Crater, then fly to Tirisfal Glades and meet us. I've marked the location on your map.", progress = "At last it is done.", completion = "I am heartened at your successful quest. We have been waiting for you to return.", objectives = "Go to Tyr's Fall in Tirisfal Glades and recover the Silver Hand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42123] = { id = 42123, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaiming Llothien" }
quests[42124] = { id = 42124, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hags and Hexes" }
quests[42125] = { id = 42125, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Whispers", description = "Felsoul Hold is not far away, but it is well defended. Very tough to get in the normal way, but Calydus can help you sneak in!\n\nThere is a portal that my kind use to haul in treasures, with it you can get in and find the skull!", completion = "Friend was able to get the skull?\n\nYes, Calydus senses it! Keep its gaze turned away from Calydus, friend. I gladly work for you without compulsion.", objectives = "Use Calydus's portal to enter into Felsoul Hold and recover the Skull of the Man'ari.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42126] = { id = 42126, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archmage Omniara", description = "Beside me is the Scouting Map. From it, you can direct our allies to carry out vital assignments across the Broken Isles.\n\nThe first task is critical. Archmage Omniara, a renowned summoner, was on her way to the Hall of Guardians when she was attacked.\n\nSend Archmage Kalecgos to help her. He will be uniquely suited to this task.", progress = "How is the mission proceeding?", completion = "Your champion did well! Archmage Omniara agreed to join us and is getting situated as we speak.", objectives = "Use the Scouting Map and complete the mission, \"Omniara Needs Help\"", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42127] = { id = 42127, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Building Our Troops", description = "Archmage Omniara is a very powerful arcanist and her skills will be quite an asset to our order.\n\nShe is capable of summoning multiple Water Elementals at the same time! Fortunately, she has agreed to share her knowledge with us.\n\nSpeak to her now, and recruit her elementals.", progress = "How did the training go?", completion = "Well done. These troops will be invaluable in our fight against the Burning Legion. Deploy them on missions, just as you would with our champions.", objectives = "Speak to Archmage Omniara and recruit some of her Water Elementals", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42128] = { id = 42128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritual Reagents", description = "The Skull of the Man'ari, oh good choice! It's very powerful and it's held by an even more powerful Dreadlord!\n\nThere is a weakness, the skull has a will of its own! If we can commune with the skull we might be able to convince it to serve you instead!\n\nWe will need reagents from the floating city before we can perform the ritual to commune with it. Dust from a fresh grave, dark oil, and a powerful alcohol catalyst.\n\nOh, and blood! I sense a beast whose blood should be perfect.", progress = "Did you obtain everything, friend?", completion = "Very good! Now, we're ready to begin.", objectives = "Search within Dalaran for Grave Dust, a Can of Overheated Oil, an Aged Snowplum Brandy, and a Stag Blood Sample.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42129] = { id = 42129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pendant of Starlight", description = "To finish my work here, I will need a magical item called the Pendant of Starlight.\n\nFor centuries, the Archdruids of the Dreamgrove passed the pendant down from one guardian to the next. But one day, a naga siren used deception to take it!\n\nThis pendant stores a great amount of arcane power... power I can use to heal the grove.\n\nGet it back, and I will be very grateful!", progress = "Was there much killing?", completion = "Yes, this is it... the pendant of the keepers! Hooray! Vengeance is so fun!", objectives = "Retrieve the Pendant of Starlight from Abyssal Queen Sha'rathra, who patrols along the coast of Val'sharah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42130] = { id = 42130, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Building Our Troops", objectives = "Speak to [Recruiter A], [Recruiter B], [Recruiter C] and train new troops.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42131] = { id = 42131, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unexpected Visitors", description = "Brace yourself, {name}. I am detecting a strange magic forming in the chamber. Something is projecting itself in.", progress = "Caria and Varedis Felsoul are like a bad copper piece that keeps coming back.", completion = "The two of them are puppets of Kil'jaeden and a bane on our existence. I am glad that you have their warglaives.\n\nThey will be that much easier to kill when we invade their world.\n\nI wonder, do you have a moment to discuss a rather urgent issue?", objectives = "Listen to your unexpected visitors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42132] = { id = 42132, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Last, But Not Least", description = "I think you already know what I am going to tell you... It is well past time to make Allari and Jace your champions.\n\nThe two of them were instrumental in the planning and preparation for the invasion of Niskara. They have earned it and you would be hard pressed to find better champions anywhere.", completion = "There is just one thing left to do.", objectives = "Recruit Allari the Souleater and Jace Darkweaver as your champions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42133] = { id = 42133, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Same Day Delivery", description = "I've enchanted these weapons to counter the natural resistances that felhounds have to magic. In addition to that, the metal should splinter their scales on impact, allowing your allies to do increased damage to the demons.\n\nWhile I don't expect the enchantment to decay over time, you should do your best to deliver these weapons to those who will use them immediately. The longer they remain here, the more demons their power will attract.", completion = "These weapons will work well against Hakkar and his minions. I'll ensure that they are distributed to our allies.", objectives = "Return to Emmarel Shadewarden at Trueshot Lodge.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42134] = { id = 42134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recruiting More Troops", description = "Our champions acquired the talents of Recruiter Sampson, an extraordinary tracker.\n\nHe has a way with animals, calling them to his side with the utmost ease. In fact, he's already beginning to fill the stables with animals that he has tracked and tamed.\n\nSpeak to him now.", completion = "It's my honor to be of service to the Unseen Path. I'll help in any way I can.", objectives = "Speak to Recruiter Sampson.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42135] = { id = 42135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Chose Strategy C" }
quests[42136] = { id = 42136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Chose Strategy A" }
quests[42137] = { id = 42137, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Yalia Sagewhisper", objectives = "Your willingness to help is admirable, and it gives me insight into what kind of leader you will be.\n\nI know you mean to gather priests from all factions and lead them in a battle against the Burning Legion. It's an extraordinary task, but one that you will not have to embark on alone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42138] = { id = 42138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Zabra Hexx", objectives = "I have a good feelin' about ya, {name}. Dis terrible day really started to turn around when ya showed up.\n\nSome might call it luck, but I think it's fate. We were meant to cross paths.\n\nDis could be da beginnin' a somethin' great.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42139] = { id = 42139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rise, Champions", description = "The Uncrowned work behind the scenes, pulling strings here, snipping others there. It's a matter of making the right choices at the right time in the most elegant manner possible.\n\nWe have all decided that you need to recruit some Shadows to send out on our most important missions. People that you can trust, or at least that you can trust to get the job done.\n\nMight I suggest that you start with Garona and Vanessa? It should prove interesting if nothing else considering recent events.", completion = "So, I guess I'll be hangin' out with Vanessa here a lot? Don't you worry 'bout nothin'.\n\nShe and I are gonna be besties.\n\nSay, you gotta moment?", objectives = "Recruit Garona Halforcen and Vanessa VanCleef as your first champions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42140] = { id = 42140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A More Wretched Hive of Scum and Villainy", description = "Word on the street is that you're lookin' to recruit some more, shall we say, unsavory types?\n\nI know just the woman! No, not me... though, I could prolly do it. But not as well as Lonika Stillblade.\n\nYeah, that Lonika. The one who founded the 'School of Roguery' in Shattrath City.\n\nSo, let's send Vanessa there out to Outland and have her make Lonika an offer she can't refuse. Or, you know, give her a legit job and a nicer location for her rogue academy.", progress = "So, what'd Lonika say?", completion = "Gold! The rogues, thieves, and cutthroats are gonna start rollin' in.\n\n<Nikki looks over at Vanessa and says in a whisper.>\n\nMaybe we'll even get some unemployed Defias to sign up. Too soon?", objectives = "Use the Scouting Map and complete the mission, \"A More Wretched Hive of Scum and Villainy\".", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42141] = { id = 42141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Summoner Morn", description = "Now that we have recruited champions of our order, we can use the Scouting Map to complete vital assignments across the Broken Isles.\n\nThe first assignment is critical. Summoner Morn, a renowned master of the elementals, was on his way to the Heart of Azeroth when he was attacked.\n\nI suggest we send Stormcaller Mylra to help him. She will be uniquely suited to this task.", progress = "How is the mission proceeding?", completion = "Good, Mylra was successful in her mission! Our recruiting efforts have paid off.", objectives = "Use the Scouting Map and complete the mission, \"Morn Needs Help\".", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42142] = { id = 42142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Recruiting The Troops", description = "Our champions acquired the talents of Summoner Morn, a powerful shaman.\n\nHe is known for his strong affinity with earth, and is a valuable addition to our Order. He is already beginning to requisition Lesser Elementals to our cause.\n\nSpeak to him now and train a Lesser Elemental.", progress = "How did the training go?", completion = "Excellent. These troops will be invaluable in our defense of the Broken Isles. Deploy them on missions, just as you would with our champions.", objectives = "Speak to Summoner Morn and summon a Lesser Elemental.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42143] = { id = 42143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Champion's Call [WIP]" }
quests[42145] = { id = 42145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out of the Woodwork" }
quests[42146] = { id = 42146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dazed and Confused and Adorable" }
quests[42147] = { id = 42147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "First Contact", description = "Time to put your new disguise to the test.\n\nYour first contact is Vanthir, a merchant from the common district. He is in the Grand Promenade today visiting one of his suppliers.\n\nTell Vanthir to pay me a visit regarding a shipment of dusk lily bulbs. He will understand.\n\nBeyond that, we will need time to prepare. You should return to Thalyssra.\n\n<Ly'leth hands you a corked bottle of faintly glowing fluid.>\n\nGive her this, with my regards. We will call upon you soon.", progress = "Have you made contact with our sympathizers?", completion = "The Lunastre family is well-connected. They will be of great help to us when the time comes.", objectives = "Speak with Vanthir in The Grand Promenade.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42148] = { id = 42148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Wine's Gone Bad" }
quests[42149] = { id = 42149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Some Knowledge Shouldn't Be Shared", description = "I noticed that quite a few of the Empyrean Society's books are inscribed with fel magic. That's blasphemous. We must confiscate as many as we can.", progress = "I hope we've found all of the books.", completion = "You'd better take those back to the Hall of the Guardian for safekeeping, {name}.", objectives = "Collect 5 Empyrean Fel Tomes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42150] = { id = 42150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kal'delar Naga Incursion" }
quests[42151] = { id = 42151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clear the Skies" }
quests[42154] = { id = 42154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Help a Whelp" }
quests[42158] = { id = 42158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Creator's Workshop", description = "My remote observation relay captured an astonishing amount of data from that tomb.\n\nIf we can download its memory to my core processing systems, I should be able to locate Titanstrike... and that unsavory vrykul who took it.\n\nSince you're here, would you mind helping out? Processing that much information might overload a few failsafe mechanisms here and there, and I know you're the capable sort!", progress = "Remember, anything is science if you write it down!", completion = "The Temple of Storms is close by, so you should get there before that thieving vrykul.", objectives = "Assist Mimiron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42159] = { id = 42159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Training with the Nightwatchers" }
quests[42160] = { id = 42160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unwelcome Visitors" }
quests[42165] = { id = 42165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsuna Specimens" }
quests[42166] = { id = 42166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Is Going On Here?", description = "We don't know much about the Empyrean Society's activities here, but now that you appear to be a new recruit you should be able to ask some questions and take a look around for the strange magic Archmage Vargoth detected. \n\nLet's meet up at the rotunda on the hill.", progress = "What do you think they are up to?", completion = "They're using fel magic. I knew there was something off about them, but I never suspected this!", objectives = "Question 5 Empyrean Society members and investigate their grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42167] = { id = 42167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Gather Bit" }
quests[42168] = { id = 42168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looking into the Darkness", description = "Friend now is ready to perform the ritual!\n\nRemember, friend, the skull must be convinced that it is in its best interest to be in your possession. If we must force the skull into your servitude, it would be far weaker.", progress = "The ritual circle is ready, friend.", completion = "Yes, Felsoul Hold! Calydus knows where that is!\n\nCalydus can make a path that connects to one of the portals there!", objectives = "Perform the ritual to commune with the Skull of the Man'ari and convince it to tell you its location.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42169] = { id = 42169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Left for Dead" }
quests[42170] = { id = 42170, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dreamweavers", description = "Assist the Druids of Val'sharah by completing 4 world quests.", completion = "The Dreamweavers thank you.", objectives = "Complete any 4 world quests in Val'sharah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42171] = { id = 42171, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Final Exit", description = "We've certainly reduced the Empyrean Society's numbers. I don't think they'll be luring any more members to their cause for a while. \n\nThere's only one place we haven't investigated, and I suspect that rune we found is attuned to the door. Let's see what's inside the building.", progress = "I thought I'd snoop around a bit before I met you at the rotunda. Unfortunately my invisibility spell wore off at an inopportune time. I'm glad you found me! What is this you have found, {name}?", completion = "Thank you for uncovering the truth about the Empyrean Society, {name}!", objectives = "Use the Rune of Opening to unlock the Empyrean Society building door.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42172] = { id = 42172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leyhollow Infestation" }
quests[42173] = { id = 42173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Electrosnack" }
quests[42174] = { id = 42174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champions of Elune" }
quests[42175] = { id = 42175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Growing Power", description = "The Tirisgarde has need of your help now that you have grown in strength, {name}. Meet me in the Hall of the Guardian when you are done with your adventures.", completion = "Good to see you here, {name}. There is much to be done!", objectives = "Meet Meryl Felstorm in the Hall of the Guardian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42176] = { id = 42176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rise of Skovald" }
quests[42177] = { id = 42177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclaiming Morheim" }
quests[42178] = { id = 42178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shock Absorber" }
quests[42182] = { id = 42182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Battle!" }
quests[42183] = { id = 42183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Battle!" }
quests[42184] = { id = 42184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Elemental Diplomacy", description = "The Lord of Tides has united with the Earthen Ring, but the matter of uniting the remaining Elemental Lords still remains.\n\nFor the next step of our campaign, I have organized a diplomatic mission to Skywall.\n\nThe goal of the mission is to ascertain the current political situation in Skywall, following the defeat of Al'Akir the Windlord, and to identify any elementals who would aid our cause.\n\nThe mission is currently waiting your assignment.", completion = "The Earthen Ring champions sent to Skywall have successfully returned to the class hall.\n\nThe plane of air is currently in a state of turmoil, however our champions identified a powerful elemental who may be willing to aid our cause.", objectives = "Successfully complete the \"Elemental Diplomacy\" mission.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42185] = { id = 42185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Never Hunt Alone", description = "Prustaga is almost certainly on her way to the Temple of Storms, which is where I imbued Titanstrike with the Thunderspark.\n\nIf my deductions are correct, she'll attempt to reverse the process and infuse the spark into herself, thus attaining the godlike power she craves!\n\nHopefully Thorim isn't off cavorting with his hounds again. If Prustaga has the local vrykul on her side, things may get... complicated.", completion = "Brann will hardly believe his ears when I tell him what happened. What an adventure!", objectives = "Seek out Thorim at the Temple of Storms and recover Titanstrike.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42186] = { id = 42186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Growing Power", description = "Iron-Body Ponshu has requested your presence.\n\nOur campaign to defend the Broken Isles is getting under way, and we need you back at the Wandering Isle.", completion = "Thank you for coming, Grandmaster.", objectives = "Speak to Iron-Body Ponshu at the Wandering Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42187] = { id = 42187, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rise, Champions", description = "We are still recovering from the attack at the Peak of Serenity.\n\nTo help us rebuild the order, we should enlist the greatest champions of our class to fight by our side.\n\nI know that the two Stormstouts, Chen and Li Li, would eagerly pledge to join the cause. Speak to them and recruit them as champions, then speak to Master Hsu.", completion = "Chen and Li Li are two of the greatest monks in recent history.\n\nAs long as they stay out of trouble, they will be great representatives of our order.", objectives = "Enlist Chen Stormstout and Li Li Stormstout, then speak to Master Hsu.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42188] = { id = 42188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nobundo Awaits", description = "Nobundo and the other champions of the Earthen Ring have gathered down below. They are awaiting your arrival, Farseer.\n\nA great ritual is about to take place and they have requested your presence. Do not worry about your administrative duties for now, I'll take care of things here.\n\nNobundo is waiting for you now. May the elements be with you, Farseer.", completion = "I hear you have been making good progress down among the Broken Isles. Good. We, too, have been busy here at the Maelstrom.\n\nThere are important matters that await us...", objectives = "Speak with Nobundo in the Heart of Azeroth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42189] = { id = 42189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Mage - Flavor Event 01" }
quests[42190] = { id = 42190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildlife Conservationist" }
quests[42191] = { id = 42191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tech It Up A Notch", description = "Thanks to you, the Order of the Broken Temple is gradually re-assembling.\n\nHowever, there is much more work to do. As our leader, you can determine the trajectory of our order's future.\n\nSpeak to Number Nine Jia. She will show you the ropes.", completion = "Excellent work, {name}! I can see that the Order of the Broken Temple is in good hands.", objectives = "Speak to Number Nine Jia.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42192] = { id = 42192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Mage - Flavor Event 02" }
quests[42193] = { id = 42193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gjallarhorn", description = "You have proven yourself most thoroughly time and again, {name}. There can be no doubt that you are the one to lead Odyn's armies into the final battle.\n\nYou must first obtain the Gjallarhorn so that you may signal to our allies that the end times are upon us.\n\nKing Svergan Stormcloak was the last known living guardian of the horn.\n\nSeek his spirit in the Field of Fallen Kings in Stormheim and see what you can learn.", completion = "What is it you seek? Are you here to pilfer heirlooms like the others?", objectives = "Find Svergan Stormcloak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42194] = { id = 42194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stolen Honor", description = "Safeguarding the Gjallarhorn was my duty, {race}. I will do what is right, but first I must ask for your aid.\n\nMy family was disavowed by the mystics of our time and this grave was ransacked.\n\nI cannot find peace while my family heirlooms are in the hands of the servants of the false God-King.\n\nReturn them to me and I will aid you in finding the Gjallarhorn!", progress = "Do you bring back my family's heirlooms, {race}?", completion = "Odyn truly guides your hand, {name}.", objectives = "Svergan Stormcloak wants you to obtain the Crown of the Forgotten King, the Stormcloak Signet and the Drakerider's Medallion in the Runewood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42197] = { id = 42197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Duke Hydraxis", objectives = "Lord Neptulon has sent me to aid the Earthen Ring in the defense of Azeroth.\n\nI have been commanded to serve the Farseer of the Earthen Ring with the same loyalty I give to the Lord of Tides. I will fulfill this duty until the Burning Legion is driven from this world and the future of Azeroth is secured.\n\nI am yours to command, Farseer.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42198] = { id = 42198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Stormcaller Mylra", objectives = "Uniting the elements won't be easy, Farseer {name}. You'll be needin' all the help you can get!\n\nAye, These are dark times indeed... but we'll face 'em t'gether, don't you worry.\n\nOl' Mylra has yer back, Farseer.\n\nNow, let's get a move on then! There ain't no time to waste!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42200] = { id = 42200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mission: Investigating Deepholm", description = "In order for the Earthen Ring to bring the four Elemental Lords together in an alliance against the Burning Legion, we will need to convince Therazane the Stonemother to join forces with us.\n\nTherazane has been absent from our negotiations with the elements thus far.\n\nThere have been whispers of a new threat arising from within Deepholm. If these rumors are true, she may have need of our aid.\n\nI have prepared a diplomatic mission to Deepholm to ascertain the situation. It is awaiting your assignment.", completion = "The mission to Deepholm was a success. The champions of the Earthen Ring made contact with Therazane, but the situation there is worse than we feared...", objectives = "Successfully complete the \"Investigating Deepholm\" mission.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42202] = { id = 42202, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Revenge, Served Cold", description = "My village was razed by a drogbar tribe who worships the very beast you seek. No one was spared.\n\nHelp me avenge my people and I will aid you in your quest to find Jorhuttam.", progress = "You return.", completion = "You have my thanks, {name}.", objectives = "Slay Dogrub the Cruel, Urgrul Skullcleaver and 8 Frostcrag Drogbar in Highmountain Summit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42203] = { id = 42203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritual Bit" }
quests[42204] = { id = 42204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jorhuttam", description = "You upheld your end of your promise. I will do the same.\n\nTake these drogbar drums. Then bang on them to call upon Jorhuttam to feast.\n\nFind the Great Worm's feeding mound and use the drums to lure her out.", progress = "The Gjallerhorn, {name}.  Is it finally in your possession?", completion = "It is done! The armies of Ulduar are bound by oath to join us now that we're in possession of the Gjallerhorn!", objectives = "Use the Frostcrag Drums near Jorhuttam's Feeding Mound and slay Jorhuttam to obtain the Gjallarhorn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42205] = { id = 42205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entrance Bit" }
quests[42206] = { id = 42206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Next Level Has Arrived", description = "The Empyrean Society is certainly much more dangerous than they appear. It's unimaginable that any mage would study fel magic -- that's for warlocks and the Legion!\n\nSince our friend, Ravandwyr, appears to be delayed, it looks like we'll have to deal with this ourselves. We should remove this sect so they can't corrupt anyone else.", progress = "Do you think we've reduced their numbers enough?", completion = "I like you, {name}. You don't hesitate to take action when necessary!", objectives = "Kill 10 Empyrean Society members.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42208] = { id = 42208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the Firelands", description = "The time has come to return to the Firelands. I need not tell you how dangerous this will be, Farseer.\n\nRagnaros may be defeated, but the elementals of the Firelands destroy with reckless abandon. Our presence there will surely be seen as an act of aggression.\n\nI have prepared a scouting mission to the Firelands. We should send only our very best champions to make contact with the elements there.\n\nIf the mission is successful, we may find the information we need to bring the Firelands into our fold.", completion = "It seems that our mission to the Firelands was a success, Farseer. We have much to discuss.", objectives = "Complete the \"Return to the Firelands\" missions.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42209] = { id = 42209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freeing the Taken" }
quests[42210] = { id = 42210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scrolls of Knowledge", description = "Our troops are ready! It's time to test them out in the field, and I have the perfect assignment.\n\nNumber Nine Jia is a well-respected scholar. She has knowledge that can help us improve the order, however, many  of her important scrolls were left behind during the attack on the Peak of Serenity.\n\nSend our champions to retrieve these documents at once!", progress = "How did it go?", completion = "It was very lucky that we were able to retrieve those scrolls. Number Nine Jia's help will be invaluable to our order.", objectives = "Complete the mission, \"Scrolls of Knowledge.\"", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42211] = { id = 42211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leodrath's Kin" }
quests[42212] = { id = 42212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Mage - Flavor Event 03" }
quests[42213] = { id = 42213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eye of Azshara: The Tidestone of Golganneth", description = "<Now that you have defeated Queen Azshara's Wrath and have the Tidestone in hand, it is time to place it in the Portrait Room of the Chamber of the Guardian in lower Dalaran.>", completion = "<Archmage Khadgar has set aside a space here for the Tidestone of Golganneth, as well as the rest of the Pillars of Creation.>", objectives = "Use the central teleporter in Dalaran and then place the Tidestone of Golganneth in the Portrait Room of the Chamber of the Guardian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42214] = { id = 42214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knocked for a Loop", description = "While you're focused on murlocs...\n\nMany murlocs are known to wear jewelry to attract a mate. I'm willing to bet that we can use some of the same jewels they use.\n\nCollect some of their jewelry and bring it back to me. The wetter, the better!", progress = "I could see how jewelry on a murloc might make it seem more attractive...", completion = "Oh yes! There are some fine looking jewels here. Let's just scratch the goop off, and...", objectives = "Collect 10 Salteye Bangles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42220] = { id = 42220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shipwrecked Sailors", description = "<The gilblin and makrura of Mak'rana have captured the forsaken sailors from the nearby shipwreck.>\n\n<It looks like the sailors are being poisoned and worse. Best to put them out of their misery.>", objectives = "Put 10 Queen's Reprisal Sailors out of their misery.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42221] = { id = 42221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chief Bitterbrine" }
quests[42222] = { id = 42222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Empyrean Society Report", description = "I find it hard to believe that Archmage Vargoth would be involved with such a malevolent group! There must be a good explanation for why he's been here... \n\nRegardless, we had best return to the Hall of the Guardian and inform Meryl about what we've uncovered here.", completion = "Ravandwyr speaks very highly of how you dealt with the Empyrean Society, {name}.", objectives = "Return to the Hall of the Guardian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42223] = { id = 42223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scouting the Crimson Thicket", description = "If you are heading east, there is something I would ask of you.\n\nWhile we struck camp some of our caravan left to scout around the city. Lilryia Dawnwind has been gone too long.\n\nI would be most grateful if you would go check on her safety. She said she was going to scout out the ruins of Dawncleft.", completion = "You could not have arrived at a better time, {race}.", objectives = "Find Lilryia Dawnwind in Dawncleft.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42224] = { id = 42224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cloaked in Moonshade", description = "I do not know what Theryn found, but I know where he found it. \n\nMoonshade Sanctum, to the west. Beyond the Temple of Fal'adora. \n\nWhatever power altered Theryn's arcane essence... Whatever power allowed Kel'danath to create a spell to soothe the withered... Its source rests there. \n\nI know this as surely as if I had been there myself.", completion = "<You recognize the relic from Thalyssra's vision.>", objectives = "Explore Moonshade Sanctum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42225] = { id = 42225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking the Seal", description = "<As you behold the relic, Thalyssra's voice echoes in your mind.>\n\nYou found it! But it is sealed away tight.\n\nSearch the room for a way to break those seals.", completion = "<As the magical barrier begins to fade, you hear the rustling of leaves and the clattering of mandibles just outside.>", objectives = "Break the Seal of the Tides, Seal of the Earth and Seal of the Sky.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42226] = { id = 42226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Moonshade Holdout", description = "<Tampering with the relic has drawn the attention of some hideous creatures from beneath Falanaar.>", completion = "Do you have any idea what you have done?!", objectives = "Slay a Fal'dorei Webslinger, a Fal'dorei Broodcaller, and a Fal'dorei Widowmaker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42227] = { id = 42227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Crevasse", description = "I have protected that seed for ten thousand years. You let it fall into the hands of the fal'dorei.\n\nI should have let you die.\n\nRepay your debt. Help me get the seed back.", completion = "We must move swiftly.", objectives = "Follow Valewalker Farodin into the Falanaar Tunnels.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42228] = { id = 42228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Hidden City", description = "Orathiss has underestimated the seed. It is sapping her power - slowing her down.\n\nWe must catch her and get the seed to safety!", completion = "<Energy pulses around the ancient seed.>", objectives = "Follow Orathiss through Falanaar Tunnels and slay her.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42229] = { id = 42229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shal'Aran", description = "The chamber beyond may be the perfect hiding place, now that its guardian has been dealt with.\n\nCome with me.", completion = "Such a temporary home will serve us well.", objectives = "Follow Thalyssra while she explores Shal'Aran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42230] = { id = 42230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Valewalker's Burden", description = "The seed is awakening. Without power it will quickly wither and die.\n\nWe must carry the seed out of here and plant it somewhere safe.\n\nI am not strong enough to bear this burden. But you... you are brimming with power. I can sense it. \n\nPlease take the seed.", completion = "<The seed sits perfectly atop the stand and sinks in with a satisfying click.>", objectives = "Activate the Fal'adora Beacon in Temple of Fal'adora.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42231] = { id = 42231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mysterious Paladin", description = "It appears we have been afforded a unique opportunity.\n\nA small order of paladins has come forward claiming to know the location of Tyr's tomb. They say they are the protectors of his warhammer, but that the ancient weapon is now imperiled.\n\nI'd like you to speak with Travard, their leader, to find out more about this artifact.", completion = "My order guards a powerful secret. We are the keepers of the final resting place of the mighty Tyr!\n\nRecent intrusions have proven his tomb's location to be a secret no longer. We must protect the sacred relic stored there... the Silver Hand!", objectives = "Speak with Travard in Dalaran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42233] = { id = 42233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Highmountain Tribes", description = "Assist the Tauren of Highmountain by completing 4 world quests.", completion = "The Highmountain tribes thank you.", objectives = "Complete any 4 world quests in Highmountain.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42234] = { id = 42234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Valarjar", description = "Assist the Vry'kul of Stormheim by completing 4 world quests.", completion = "The valarjar thank you.", objectives = "Complete any 4 world quests in Stormheim.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42235] = { id = 42235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasion: Westfall" }
