quests[42237] = { id = 42237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasion: Tanaris" }
quests[42238] = { id = 42238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing Demon", description = "I seem to have misplaced my imp, Daglop.\n\nIf you see him, tell him to check in.\n\nNormally I would just resummon him but I'm worried blind Marius here will kill him first and ask questions later.\n\nNo vision, that one.", completion = "Yeah yeah, the new master sent you. I get it. I have to deal with my former master first.", objectives = "Find Daglop in Azsuna.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[42239] = { id = 42239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halls of Valor: The Bear King" }
